import React, { useState } from 'react';
import './FriendsPage.css';

const mockFriends = [
  { userId: 1, username: 'johndoe', displayName: 'John Doe' },
  { userId: 2, username: 'alicesmith', displayName: 'Alice Smith' },
  { userId: 3, username: 'mikejones', displayName: 'Mike Jones' },
  { userId: 4, username: 'saralee', displayName: 'Sara Lee' },
];

const mockReceived = [
  { friendshipId: 5, username: 'bobross', displayName: 'Bob Ross' },
];

const mockSent = [
  { friendshipId: 6, username: 'janedoe', displayName: 'Jane Doe' },
];

function getInitials(displayName) {
  return displayName.split(' ').map(w => w[0]).join('').toUpperCase();
}

function FriendsPage() {
  const [activeTab, setActiveTab] = useState('friends');
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResult, setSearchResult] = useState(null);

  function handleSearch() {
    // Mock search — later this will call /api/friends/search
    if (searchQuery.trim() === '') return;
    setSearchResult({ username: searchQuery, displayName: searchQuery });
  }

  return (
    <div className="friends-container">
      <h1 className="friends-title">Friends</h1>

      {/* Search Bar */}
      <div className="search-bar">
        <input
          type="text"
          placeholder="Search users by username..."
          value={searchQuery}
          onChange={e => setSearchQuery(e.target.value)}
          className="search-input"
        />
        <button className="search-btn" onClick={handleSearch}>Search</button>
      </div>

      {/* Search Result */}
      {searchResult && (
        <div className="search-result">
          <div className="friend-card">
            <div className="friend-avatar">{getInitials(searchResult.displayName)}</div>
            <div className="friend-info">
              <span className="friend-username">{searchResult.username}</span>
              <span className="friend-displayname">{searchResult.displayName}</span>
            </div>
            <button className="btn-add">Add Friend</button>
          </div>
        </div>
      )}

      {/* Tabs */}
      <div className="tabs">
        <button
          className={`tab ${activeTab === 'friends' ? 'tab-active' : ''}`}
          onClick={() => setActiveTab('friends')}
        >
          My Friends ({mockFriends.length})
        </button>
        <button
          className={`tab ${activeTab === 'received' ? 'tab-active' : ''}`}
          onClick={() => setActiveTab('received')}
        >
          Received ({mockReceived.length})
        </button>
        <button
          className={`tab ${activeTab === 'sent' ? 'tab-active' : ''}`}
          onClick={() => setActiveTab('sent')}
        >
          Sent ({mockSent.length})
        </button>
      </div>

      {/* Tab Content */}
      <div className="tab-content">

        {activeTab === 'friends' && (
          <div className="friends-grid">
            {mockFriends.map(friend => (
              <div key={friend.userId} className="friend-card">
                <div className="friend-avatar">{getInitials(friend.displayName)}</div>
                <div className="friend-info">
                  <span className="friend-username">{friend.username}</span>
                  <span className="friend-displayname">{friend.displayName}</span>
                </div>
                <button className="btn-remove">Remove</button>
              </div>
            ))}
          </div>
        )}

        {activeTab === 'received' && (
          <div className="friends-grid">
            {mockReceived.map(req => (
              <div key={req.friendshipId} className="friend-card">
                <div className="friend-avatar">{getInitials(req.displayName)}</div>
                <div className="friend-info">
                  <span className="friend-username">{req.username}</span>
                  <span className="friend-displayname">{req.displayName}</span>
                </div>
                <div className="request-actions">
                  <button className="btn-accept">Accept</button>
                  <button className="btn-decline">Decline</button>
                </div>
              </div>
            ))}
          </div>
        )}

        {activeTab === 'sent' && (
          <div className="friends-grid">
            {mockSent.map(req => (
              <div key={req.friendshipId} className="friend-card">
                <div className="friend-avatar">{getInitials(req.displayName)}</div>
                <div className="friend-info">
                  <span className="friend-username">{req.username}</span>
                  <span className="friend-displayname">{req.displayName}</span>
                </div>
                <span className="pending-label">Pending</span>
              </div>
            ))}
          </div>
        )}

      </div>
    </div>
  );
}

export default FriendsPage;
